  $$('input[name=pz-w]').forEach(function(x){x.onchange=function(){D.when=x.value;if(D.when==='plan'&&!D.plan_at){var t=new Date(Date.now()+7*3600e3+864e5);D.plan_at=t.toISOString().slice(0,10)+'T08:00'}pzCompose()}});
