/* ── N5 ยืนยัน + ส่ง ── */
function pzSubmit(test,btn){var D=PZ.draft,im=D.image_id?pzImg(D.image_id):null,c=pzCalc(D.targets);
  if(!im&&!String(D.text).trim())return toast('เลือกภาพ หรือพิมพ์ข้อความ',1);
  if(im){var t=pzTapRead();Object.assign(D,t);if(D.tap==='link'&&!/^https:\/\/\S{3,}/.test(D.link))return toast('ลิงก์ต้องขึ้นต้นด้วย https://',1)}
  var payload={image_id:D.image_id,text:D.text,tap:im?D.tap:'none',go:D.go,link:D.link,targets:D.targets,when:D.when,plan_at:D.plan_at,test:test};
  if(test)return pzFire(payload,btn,'ส่งทดสอบถึงฉัน');
  if(!D.targets.length)return toast('เลือกผู้รับ',1);if(!c.reach&&!c.groups)return toast('ผู้รับที่เลือกยังไม่มีใครเชื่อม LINE',1);if(D.when==='plan'&&!D.plan_at)return toast('เลือกวันและเวลาส่ง',1);
  var names=D.targets.map(function(t){return pzTgName(t)[0]}),plan=D.when==='plan';
  pzModal(plan?'ยืนยันตั้งเวลาส่ง?':'ยืนยันส่งตอนนี้?',plan?'ยกเลิกได้จนถึงเวลาส่ง':'ส่งแล้วดึงคืนจากแชตไม่ได้',
   (im?'<div class="pz-cfi"><span class="pz-th sm'+(im.kind==='float'?' pz-chk':'')+'"><img src="'+esc(pzSrc(im,240))+'" alt=""></span><div><b>'+esc(im.title)+'</b><small>'+(im.kind==='float'?'ภาพลอย':'ภาพปกติ')+' · กดภาพ: '+esc(pzTapTxt(D))+'</small>'+(D.text?'<small>+ ข้อความ '+D.text.length+' ตัวอักษร'+(LM_PH_.test(D.text)?' (แทรกชื่อรายคน)':'')+'</small>':'')+'</div></div>':'<div class="pz-cfi"><div><b>ข้อความอย่างเดียว</b><small>'+esc(D.text.slice(0,120))+'</small></div></div>')+
   '<div class="pz-cfr">'+pzI('clock',16)+'<span>เวลาส่ง</span><b>'+(plan?pzDt(D.plan_at):'ทันที')+'</b></div><div class="pz-cfr">'+pzI('users',16)+'<span>พนักงาน</span><b>'+c.reach+' คน</b></div><div class="pz-cfs">'+esc(names.slice(0,12).join(' · '))+(names.length>12?' · และอีก '+(names.length-12)+' รายการ':'')+'</div>'+
   (c.groups?'<div class="pz-cfr">'+pzI('chat',16)+'<span>กลุ่ม LINE</span><b>'+c.groups+' กลุ่ม</b></div>':'')+(c.nolink.length?'<div class="pz-cfr pz-wn">'+pzI('alert',16)+'<span>ไม่ได้รับ (ยังไม่เชื่อม LINE)</span><b>'+c.nolink.length+' คน</b></div><div class="pz-cfs">'+esc(c.nolink.slice(0,8).map(function(p){return p.name}).join(' · '))+(c.nolink.length>8?' · …':'')+'</div>':'')+
   '<div class="pz-warn">'+pzI('alert',15)+'ส่งแล้วดึงคืนจากแชตไม่ได้ · ถ้าต้องการลองดูก่อน กด ส่งทดสอบถึงฉัน</div>'+(c.reach+c.groups>=100?'<label class="pz-l">พิมพ์จำนวนผู้รับ <b>'+(c.reach)+'</b> เพื่อยืนยัน<input id="pz-cn" inputmode="numeric" autocomplete="off"></label>':''),
   '<button class="btn" id="pz-c">'+pzI('left',15)+' กลับไปแก้</button><button class="btn '+(plan?'pri':'pz-line')+'" id="pz-ok">'+(plan?pzI('clock',15)+' ยืนยันตั้งเวลา':pzI('send',15)+' ยืนยันส่ง')+'</button>',620);
  $('#pz-c').onclick=pzClose;$('#pz-ok').onclick=function(){var cn=$('#pz-cn');if(cn&&+cn.value!==c.reach){toast('พิมพ์จำนวนผู้รับให้ตรง',1);cn.focus();return}pzFire(payload,this,plan?'ตั้งเวลา':'ส่ง')}}
function pzFire(p,btn,lab){busy(btn,1);aCall('lmCreate',p).then(function(s){if(s.status==='scheduled'){pzClose();toast('ตั้งเวลาส่งแล้ว · '+pzDt(s.plan_at));PZ.draft=null;PZ.tab='plan';return pzLoad()}return pzRunLoop(s,p.test)}).catch(function(e){busy(btn,0);toast(e.message,1)})}
function pzRunLoop(s,test){var prog=function(x){pzModal(test?'กำลังส่งทดสอบ…':'กำลังส่งประกาศ…','อย่าปิดหน้านี้จนกว่าจะเสร็จ (ปิดแล้วระบบส่งต่อเองภายใน 5 นาที)','<div class="pz-prog"><i><b style="width:'+(x.size?Math.round(x.done/x.size*100):5)+'%"></b></i><span>'+(x.size?x.done+' / '+x.size:'กำลังเตรียมรายชื่อ…')+'</span></div>','',480);$('#pz-x').style.display='none';$('#pz-bg').onclick=null};
  prog(s);var step=function(){aCall('lmDispatch',s.id).then(function(r){if(r.status==='sending'||r.status==='queued'){prog(r);return setTimeout(step,200)}pzDone(r,test)}).catch(function(e){pzClose();toast('ส่งไม่สำเร็จ: '+e.message+' · ดูในประวัติการส่ง',1);PZ.draft=null;PZ.tab='hist';pzLoad()})};step()}
function pzDone(r,test){pzClose();var m=r.status==='skipped_dev'?'ระบบทดสอบ · ไม่ได้ส่ง LINE จริง ('+(r.sent+r.groups_sent)+' รายการ)':r.status==='sent'?(test?'ส่งทดสอบถึงคุณแล้ว · ดูในแชต LINE':'ส่งแล้ว '+r.sent+' คน'+(r.groups_sent?' + '+r.groups_sent+' กลุ่ม':'')):r.status==='partial'?'ส่งแล้ว '+r.sent+' คน · ไม่สำเร็จ '+r.failed+' รายการ':'ส่งไม่สำเร็จ'+(r.err?': '+r.err:'');
  toast(m,r.status==='error'||r.status==='partial');if(!test){PZ.draft=null;PZ.tab='hist'}pzLoad()}

/* ── N6 ประวัติ / ตั้งเวลาไว้ ── */
function pzHist(plan){var q=PZ.hq.trim().toLowerCase(),F=[['all','ทั้งหมด'],['sent','ส่งแล้ว'],['partial','ไม่สำเร็จบางส่วน'],['test','ทดสอบ'],['cancelled','ยกเลิก']];
  var L=PZ.d.sends.filter(function(s){if(plan)return s.status==='scheduled';if(PZ.hf==='test')return s.test;if(PZ.hf==='sent')return !s.test&&s.status==='sent';if(PZ.hf==='partial')return /^(partial|error)$/.test(s.status);if(PZ.hf==='cancelled')return s.status==='cancelled';return true})
   .filter(function(s){return !q||((s.image?s.image.title:'')+' '+s.text+' '+s.label.join(' ')+' '+s.by).toLowerCase().indexOf(q)>=0});
  if(plan)L.sort(function(a,b){return a.plan_at<b.plan_at?-1:1});
  $('#pz-body').innerHTML=(plan?'':'<div class="pz-fr"><label class="pz-srch">'+ic('search')+'<input id="pz-hq" type="search" placeholder="ค้นหาประกาศ ผู้รับ หรือผู้ส่ง" value="'+esc(PZ.hq)+'"></label>'+F.map(function(f){return '<button class="chip" data-pzhf="'+f[0]+'" aria-pressed="'+(PZ.hf===f[0])+'">'+f[1]+'</button>'}).join('')+'</div>')+
   (L.length?'<div class="card pz-tbl"><table><thead><tr><th>'+(plan?'เวลาที่จะส่ง':'วันเวลาส่ง')+'</th><th>ประกาศ</th><th>ผู้รับ</th><th>ผลการส่ง</th><th>ผู้ส่ง</th><th>สถานะ</th></tr></thead><tbody>'+L.map(function(s){var lb=s.label.slice(0,2).join(' · ')+(s.label.length>2?' +'+(s.label.length-2):'');
     return '<tr data-pzd="'+s.id+'"><td><b>'+(s.status==='scheduled'?pzDt(s.plan_at):pzDt(s.sent_at||s.created_at))+'</b>'+(s.plan_at&&s.status!=='scheduled'?'<small>ตั้งเวลาไว้</small>':'')+'</td><td><div class="pz-tc">'+(s.image?'<span class="pz-th xs'+(s.image.kind==='float'?' pz-chk':'')+'"><img src="'+esc(pzSrc(s.image,240))+'" alt="" loading="lazy"></span>':'<span class="pz-th xs pz-tx">'+pzI('text',16)+'</span>')+'<span><b>'+esc(s.image?s.image.title:s.text.slice(0,40))+'</b><small>'+(s.image?(s.image.kind==='float'?'ภาพลอย':'ภาพปกติ')+(s.text?' + ข้อความ':''):'ข้อความอย่างเดียว')+'</small></span></div></td>'+
      '<td>'+esc(lb)+'</td><td>'+(s.status==='scheduled'||s.status==='cancelled'?'—':'<b>'+s.sent+' / '+(s.total-s.nolink)+' คน</b>'+(s.groups?'<small>'+s.groups_sent+' / '+s.groups+' กลุ่ม</small>':'')+(s.tap!=='none'&&!s.test?'<small>กดภาพ '+(s.clicks+s.link_hits)+' ครั้ง</small>':''))+'</td><td>'+esc(s.by)+'</td><td>'+pzBadge(s.status,s.test)+'</td></tr>'}).join('')+'</tbody></table></div>':'<div class="card state"><b>'+(plan?'ไม่มีรายการที่ตั้งเวลาไว้':'ยังไม่มีประวัติการส่ง')+'</b><span>'+(plan?'สร้างประกาศแล้วเลือก "ตั้งเวลา"':'')+'</span></div>')+
   (plan?'':'<div class="pz-note">กดภาพ = จำนวนคนที่กดภาพแล้วเปิดแอป (LINE ไม่บอกว่าใครอ่านแล้ว ระบบนับจากการกดแทน)</div>');
  var hq=$('#pz-hq');if(hq)hq.oninput=function(){PZ.hq=hq.value;var p=hq.selectionStart;pzHist(plan);var n=$('#pz-hq');n.focus();n.setSelectionRange(p,p)};
  $$('[data-pzhf]').forEach(function(b){b.onclick=function(){PZ.hf=b.dataset.pzhf;pzHist(plan)}});$$('[data-pzd]').forEach(function(tr){tr.onclick=function(){pzDetail(tr.dataset.pzd)}})}

/* ── N7 รายละเอียดการส่ง ── */
function pzDetail(id){drawer('รายละเอียดการส่ง','<div class="loading"><span class="spin"></span>กำลังโหลด…</div>');aCall('lmDetail',id).then(function(s){pzDetDraw(s,'all')}).catch(function(e){$('.drw .cb').innerHTML='<div class="alert">'+esc(e.message)+'</div>'})}
function pzDetDraw(s,f){var R=s.recips||[],ST={sent:['ส่งแล้ว','ok'],dev:['ระบบทดสอบ','g'],fail:['ไม่สำเร็จ','bad'],nolink:['ยังไม่เชื่อม LINE · ไม่ได้ส่ง','warn'],wait:['รอส่ง','g'],click:['ได้รับผ่านกลุ่ม','g']};
  var bad=R.filter(function(r){return r.s==='fail'||r.s==='nolink'}),grp=R.filter(function(r){return r.k==='g'}),ck=R.filter(function(r){return r.c}),L=f==='bad'?bad:f==='grp'?grp:f==='ck'?ck:R;
  var cb=$('.drw .cb');if(!cb)return;$('.drw h3').textContent=s.image?s.image.title:'ข้อความ';
  cb.innerHTML='<div class="pz-dt">'+(s.image?'<span class="pz-th md'+(s.image.kind==='float'?' pz-chk':'')+'"><img src="'+esc(pzSrc(s.image,460))+'" alt=""></span>':'')+'<div><div>'+pzBadge(s.status,s.test)+'</div><small>'+(s.status==='scheduled'?'จะส่ง '+pzDt(s.plan_at):'ส่ง '+pzDt(s.sent_at||s.created_at))+' · โดย '+esc(s.by)+'</small><small>กดภาพ: '+esc(pzTapTxt(s))+'</small><small>ผู้รับ: '+esc(s.label.join(' · '))+'</small>'+(s.text?'<div class="pz-dtx">'+esc(s.text).replace(/\n/g,'<br>')+'</div>':'')+(s.err?'<div class="alert">'+esc(s.err)+'</div>':'')+'</div></div>'+
   (s.status!=='scheduled'&&s.status!=='cancelled'?'<div class="pz-dk"><div><small>ส่งถึง</small><b>'+s.sent+' คน</b></div><div class="'+(bad.length?'pz-wn':'')+'"><small>ไม่ได้รับ</small><b>'+bad.length+'</b></div><div><small>กลุ่ม LINE</small><b>'+s.groups_sent+' / '+s.groups+'</b></div><div><small>กดภาพ</small><b>'+(s.clicks+s.link_hits)+'</b></div></div>':'')+
   '<div class="pz-dac">'+(s.status==='scheduled'?'<button class="btn sm pri" id="pz-now">'+pzI('send',14)+' ส่งตอนนี้</button><button class="btn sm" id="pz-can">ยกเลิกการส่ง</button>':'')+(/^(partial|error)$/.test(s.status)&&R.some(function(r){return r.s==='fail'})?'<button class="btn sm pri" id="pz-rt">'+pzI('refresh',14)+' ส่งซ้ำเฉพาะที่ไม่สำเร็จ ('+R.filter(function(r){return r.s==='fail'}).length+')</button>':'')+(s.status==='sending'||s.status==='queued'?'<button class="btn sm pri" id="pz-cont">'+pzI('send',14)+' ส่งต่อ</button>':'')+(!s.test?'<button class="btn sm" id="pz-cp">'+pzI('copy',14)+' ใช้เป็นประกาศใหม่</button>':'')+'</div>'+
   (R.length?'<div class="pz-dch">'+[['all','ทั้งหมด '+R.length],['bad','ไม่ได้รับ '+bad.length],['grp','กลุ่ม LINE '+grp.length],['ck','กดภาพ '+ck.length]].map(function(x){return '<button class="chip" data-pzdf="'+x[0]+'" aria-pressed="'+(f===x[0])+'">'+x[1]+'</button>'}).join('')+'</div><div class="pz-dl">'+
    L.map(function(r){var t=ST[r.s]||[r.s,'g'];return '<div class="pz-dr"><span class="pz-av">'+esc(String(r.name||'?').slice(0,1))+'</span><span class="pz-drt"><b>'+esc(r.name)+'</b><small>'+esc(r.sub||(r.code?'รหัส '+r.code:''))+(r.e?' · '+esc(r.e):'')+'</small></span>'+(r.c?'<small class="pz-ckt">กดภาพ '+esc(pzDt(r.c).split(' · ')[1]||'')+'</small>':'')+'<span class="pz-b pz-b-'+t[1]+'">'+t[0]+'</span></div>'}).join('')+'</div>':'<div class="faint">'+(s.status==='scheduled'?'รายชื่อผู้รับนับตอนส่งจริง':'ไม่มีรายชื่อ')+'</div>')+
   '<div class="faint pz-s">ส่งซ้ำได้เฉพาะคนที่ LINE ตอบไม่สำเร็จ · คนที่ยังไม่เชื่อม LINE ต้องเชื่อมก่อน (ส่งลิงก์เชิญในหน้าพนักงาน)</div>';
  $$('[data-pzdf]').forEach(function(b){b.onclick=function(){pzDetDraw(s,b.dataset.pzdf)}});
  var act=function(fn,ok){return function(){var b=this;busy(b,1);aCall(fn,s.id).then(function(r){if(ok)toast(ok);closeD();if(r.status==='queued'||r.status==='sending')return pzRunLoop(r,r.test);pzLoad()}).catch(function(e){busy(b,0);toast(e.message,1)})}};
  var nw=$('#pz-now');if(nw)nw.onclick=act('lmSendNow');var cn=$('#pz-can');if(cn)cn.onclick=function(){var b=this;ask({title:'ยกเลิกการส่งนี้?',desc:'ตั้งเวลาไว้ '+pzDt(s.plan_at),tone:'warn',buttons:[{k:'no',label:'ไม่ยกเลิก'},{k:'yes',label:'ยกเลิกการส่ง',cls:'pri'}]}).then(function(k){if(k==='yes')act('lmCancel','ยกเลิกแล้ว').call(b)})};
  var rt=$('#pz-rt');if(rt)rt.onclick=act('lmRetry');var co=$('#pz-cont');if(co)co.onclick=function(){closeD();pzRunLoop(s,s.test)};
  var cp=$('#pz-cp');if(cp)cp.onclick=function(){closeD();PZ.draft={image_id:s.image&&pzImg(s.image.id)&&pzImg(s.image.id).status==='active'?s.image.id:'',text:s.text,tap:s.tap,go:s.go,link:s.link,targets:s.targets.filter(function(t){return t.t!=='me'}),when:'now',plan_at:'',pv:'emp'};pzCompose()}}
